def unit_of_work(metadata=None, timeout=None):
    def decorator(func):
        def wrapper(tx):
            with tx.run() as cursor:
                if metadata:
                    cursor.set_meta(metadata)
                if timeout:
                    cursor.set_timeout(timeout)
                return func(tx, cursor)
        return wrapper
    return decorator

