def round_half_to_even(n):
    """Round a number to the nearest even integer, or to
    the nearest integer if the number is halfway between two
    even integers.

    :param n: A number
    :return: The rounded number
    """
    if n == int(n):
        return n
    else:
        return int(n + 1) if n % 2 == 1 else int(n)

