def extostr(cls, e, max_level=30, max_path_level=5):
    import traceback
    import sys

    def _format_exception(etype, value, tb, max_level=30, max_path_level=5):
        if etype == SyntaxError or etype == NameError:
            return value

        msg = traceback.format_exception_only(etype, value)
        msg = ''.join([x.rstrip() for x in msg])

        stack = []
        curr_tb = tb
        while max_level > 0 and curr_tb is not None:
            stack.append(curr_tb.tb_frame.f_code.co_filename)
            curr_tb = curr_tb.tb_next
            max_level -= 1

        path_stack = []
        curr_tb = tb
        while max_level > 0 and curr_tb is not None:
            path_stack.append(curr_tb.tb_frame.f_code.co_filename)
            curr_tb = curr_tb.tb_next
            max_level -= 1

        if path_stack:
            msg += '\nCall stack:\n' + '\n'.join('- {}'.format(x) for x in path_stack)

        if len(stack) > max_path_level:
            stack = stack[:max_path_level] + ['...']

        msg += '\nCall path:\n' + '\n'.join('- {}'.format(x) for x in stack)
        return msg

    outcome = _format_exception(e.__class__, e, e.__traceback__, max_level, max_path_level)
    if outcome and outcome.startswith("Exception in thread"):
        return outcome.split(":")[1].strip()

    return outcome

