def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if not isinstance(sequence, (list, tuple)):
        sequence = [sequence]

    normalized_args = []

    for arg in sequence:
        if isinstance(arg, (Declaration, tuple)):
            normalized_args.append(arg)
        elif isinstance(arg, Interface):
            # expand implements specs
            if isinstance(output, Interface):
                # output interface
                normalized_args.append(InterfaceImplementsSpec(arg, output))
            else:
                # expand single interface
                for i in arg.all_implements_specs:
                    normalized_args.append(InterfaceImplementsSpec(i))
        elif isinstance(arg, MultiLangStr):
            # generate definitions for all languages
            for lang, text in arg.strings.items():
                normalized_args.append(Definition(lang, text))
        elif isinstance(arg, Language):
            # generate definition for language
            text = arg.text
            if text:
                normalized_args.append(Definition(arg.tag, text))
        elif isinstance(arg, Support):
            # expand support specs
            for spec in arg.all_support_specs:
                normalized_args.append(spec)
        elif isinstance(arg, MultiLangFlt):
            # generate definitions for all languages
            for lang, text in arg.strings.items():
                normalized_args.append(FloatingPointDefinition(lang, text))
        elif isinstance(arg, SupportFlt):
            # expand support specs
            for spec in arg.all_support_specs:
                normalized_args.append(spec)
        else:
            raise ValueError("Unsupported arg type: " + str(type(arg)))

    return normalized_args

