def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
"""

    def _filter_invalid(labels):
        """Check whether the given labels are valid and raise a ValidationError if not.

        Args:
            labels (dict): the labels to validate.

        Returns:
            dict: the given labels if they are valid, an empty dictionary otherwise.
        """

        for key, value in labels.items():
            if not re.fullmatch(REGEX_LABEL_KEY, key):
                raise ValidationError(
                    f"Label key '{key}' does not match the regex {REGEX_LABEL_KEY}",
                )

            if isinstance(value, list):
                for elem in value:
                    if not re.fullmatch(REGEX_LABEL_VALUE, elem):
                        raise ValidationError({value}, f"Label value '{key}' does not match the regex {REGEX_LABEL_VALUE}")
            else:
                if not re.fullmatch(REGEX_LABEL_VALUE, value):
                    raise ValidationError({value}, f"Label value '{key}' does not match the regex {REGEX_LABEL_VALUE}")

        return labels

    try:
        return _filter_invalid(labels)
    except ValidationError as err:
        raise ValidationError({k: v for k, v in err.messages}, err.message) from None)

