def generate_observer_schema(obj):
    """
    Generate an observer schema for a Kubernetes resource or a subresource.

    Args:
        obj (Resource or Subresource): The object for which to generate an observer schema
    """
    schema = {
        "schema": {
            "properties": {
                "custom-annotations": {
                    "type": "object",
                    "properties": {},
                    "required": [],
                    "additionalProperties": {
                        "type": "object",
                        "properties": {},
                        "required": [],
                        "additionalProperties": {
                            "type": "array",
