                    "properties": {},
                    "required": [],
                    "additionalProperties": {
                        "type": "object",
                        "properties": {},
                        "required": [],
                        "additionalProperties": {
                            "type": "string"
                        }
                    }
                },
                "metadata": {
                    "type": "object",
                    "properties": {},
                    "required": [],
                    "additionalProperties": {
                        "type": "object",
                        "properties": {},
                        "required": [],
                        "additionalProperties": {
                            "type": "string"
                        }
                    }
                }
            },
            "required": [],
            "additionalProperties": {
                "type": "object",
                "properties": {},
                "required": [],
                "additionalProperties": {
                    "type": "array",
                    "items": {
                        "type": "string"
                    }
                }
            }
        },
        "relations": {},
        "indexes": {},
        "roles": {}
    }

    for prop in obj.properties:
        if prop.name not in ["custom-annotations", "status", "metadata"]:
            schema["schema"]["properties"][prop.name] = {
                "type": "string"
            }

    for subscription in obj.subscriptions:
        schema["relations"][subscription.name] = {
            "type": "one-to-many",
            "foreign_key": subscription.foreign_key,
            "child_key": subscription.child_key,
            "abstract_subscription": subscription.abstract_subscription
        }

    for index in obj.indexes:
        schema["indexes"][index.name] = index.key

    for role in obj.roles:
        schema["roles"][role.name] = role.definition

    return schema

