    if not isinstance(params, (dict, list)):
        raise TypeError("'params' must be a dict or list, not " + str(type(params)))
    if self.in_style:
        if isinstance(params, list):
            params = {str(i + 1): v for i, v in enumerate(params)}
        if not all(isinstance(k, str) and isinstance(v, bytes) for k, v in params.items()):
            raise TypeError("'params' must be a dict mapping str keys to bytes values")
        if self.parameter_indexes_str:
            sql = sql.format(**params)
        else:
            placeholders = {k: "%:" + k for k in params.keys()}
            sql = sql % placeholders
    else:
        if not all(isinstance(v, bytes) for v in params):
            raise TypeError("'params' must be a dict mapping str keys to bytes values")
        if self.parameter_indexes_str:
            sql = sql.format_map(params)
        else:
            placeholders = {str(i + 1): v for i, v in enumerate(params)}
            sql = sql % placeholders

