def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    # Verify that the object at the given path is a directory
    if path.is_file():
        raise ValueError("Path is not a directory: " + str(path))

    # Match the OCFL directory structure
    if not path.name.startswith("ocfl"):
        raise ValueError("Path does not match OCFL directory structure: " + str(path))
    if not (path / "description").is_file():
        raise ValueError("Path does not contain a description file: " + str(path))
    if not (path / "head" / "identification").is_file():
        raise ValueError("Path does not contain an identification file: " + str(path))
    if not (path / "content").is_dir():
        raise ValueError("Path does not contain a content directory: " + str(path))

    # Check for duplicate IDs
    id_map = {}
    for dirpath, dirnames, filenames in os.walk(path / "content"):
        for filename in filenames:
            if filename.startswith("ocfl_object"):
                id = filename.split("_")[1]
                if id in id_map:
                    raise ValueError("Duplicate ID detected: " + id + " in " + str(path))
                else:
                    id_map[id] = True

    # Check for expected files
    for dirpath, dirnames, filenames in os.walk(path / "content"):
        for filename in filenames:
            if filename.startswith("ocfl_object") and filename.endswith(".json"):
                with open(os.path.join(dirpath, filename), "r") as f:
                    data = json.load(f)
                    if data["type"] != "ocfl_object":
                        raise ValueError("Invalid object file type: " + filename + " in " + str(path))
                    if data["id"] not in id_map:
                        raise ValueError("ID not found in directory structure: " + data["id"] + " in " + str(path))
                    if data["id"] in id_map and id_map[data["id"]] != True:
                        raise ValueError("Duplicate ID detected: " + data["id"] + " in " + str(path))
                    id_map[data["id"]] = False
            elif filename.startswith("ocfl_file"):
                with open(os.path.join(dirpath, filename), "r") as f:
                    data = json.load(f)
                    if data["type"] != "ocfl_file":
                        raise ValueError("Invalid file file type: " + filename + " in " + str(path))
    return True

