def get_config():
    config = VersioneerConfig()

    # Populate the config object with data from the `versioneer` section of the `setup.cfg` file
    with open('setup.cfg') as f:
        for line in f:
            if line.startswith('[versioneer]'):
                continue
            if line.startswith('#'):
                continue
            if line.strip() == '':
                continue
            key, value = line.split('=')
            config.__dict__[key] = value.strip()

    # Populate the config object with data from the `__version__` module
    with open('__version__.py') as f:
        for line in f:
            if line.startswith('__version__ ='):
                config.version = line.split('=')[1].strip().strip('"')

    # Return the populated config object
    return config

