def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """
    Validate storage root hierarchy.

    Parameters:
    validate_objects (bool): Specifies whether to validate all objects in the hierarchy. Default is True.
    check_digests (bool): Specifies whether to verify the integrity of the data in the hierarchy by checking the digests of the objects. Default is True.
    show_warnings (bool): Specifies whether to print warnings for any issues found. Default is False.

    Returns:
    num_objects (int): Number of objects checked.
    good_objects (int): Number of objects checked that were found to be valid.
    """

    # Check all objects in the hierarchy
    if validate_objects:
        for obj in self.iterobjects():
            # Convert object to storage format if necessary
            if isinstance(obj, str):
                obj = self.storage.read_object(obj)

            # Validate object
            try:
                obj.validate()
            except Exception:
                if show_warnings:
                    print(f"Error validating object {obj.id}: {format_exc()}")

    # Verify integrity of data in the hierarchy by checking digests
    if check_digests:
        for obj in self.iterobjects():
            # Convert object to storage format if necessary
            if isinstance(obj, str):
                obj = self.storage.read_object(obj)

            # Check digest
            if obj.digest:
                try:
                    obj.check_digest()
                except Exception:
                    if show_warnings:
                        print(f"Error checking digest for object {obj.id}: {format_exc()}")

    # Count number of valid and total objects
    num_objects = len(self.iterobjects())
    good_objects = len([obj for obj in self.iterobjects() if obj.valid])

    return num_objects, good_objects

