def bash_completion():
    """
    Return a bash completion script for the borgmatic command. Produce this by introspecting
    borgmatic's command-line argument parsers.
    """
    # Get the list of commands and subcommands from the root parser
    commands = []
    subcommands = []
    for action in parser._actions:
        if isinstance(action, argparse._SubParsersAction):
            for subcommand, subparser in action.choices.items():
                subcommands.append(subcommand)
                for subsubcommand, subsubparser in subparser._option_string_actions.items():
                    subcommands.append(subsubcommand)
    # Get the list of options and arguments for each command
    options = {}
    arguments = {}
    for command in commands:
        options[command] = []
        arguments[command] = []
        for action in parser._option_string_actions.values():
            if action.dest:
                if action.option_strings and action.option_strings[0] in ("-h", "--help"):
                    # Ignore the help option
                    continue
                if action.option_strings and action.option_strings[0] in ("--", "-"):
                    # Ignore positional arguments
                    continue
                if len(action.option_strings) == 1 and action.option_strings[0][0] == "-":
                    # Ignore single-dash options
                    continue
                options[command].append(action.option_strings[0])
    # Generate the completion script
    script = "# bash completion for borgmatic\n"
    script += "AC_OUTPUT()\n"
    script += "AC_ARG_CMD([--], [1], null, null)\n\n"
    script += "AC_ARG_CMD([borgmatic], [1], null, null)\n\n"
    for command in commands:
        script += "AC_ARG_SUBCMD([{0}], [1], [{1}])\n".format(command, " ".join(options[command]))
        for subcommand in subcommands:
            if subcommand.startswith(command + "-"):
                script += "AC_ARG_CMD([{0}], [2], [{1}])\n".format(subcommand, " ".join(options[subcommand]))
    script += "complete -F __melior bash\n"
    import subprocess
    import io
    p = subprocess.Popen(["bash", "-c", script], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    out, err = p.communicate()
    return io.TextIOWrapper(p.stdout).read()

