            # Parse arg using subparser
            parsed_args[arg] = subparsers[arg].parse_args(unparsed_arguments)
            # Add subparser to list of found subparsers
            found_subparsers.add(arg)
        else:
            # Check if arg is for a positional arg not claimed by any subparser
            for subparser in subparsers.values():
                if subparser.convert_arg(arg) is not None:
