            else:
                # Create new ArgumentParser instance for arg
                subparsers[arg] = ArgumentParser()
                # Parse arg using new subparser
                parsed_args[arg] = subparsers[arg].parse_args([arg])
                # Add subparser to list of found subparsers
                found_subparsers.add(arg)

    return parsed_args, [arg for arg in unparsed_arguments if arg not in found_subparsers]

