def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """
    Call the given command(s).

    Arguments:
        commands (list of str): The commands to be executed.
        args (list of str): The arguments for each command.
        cwd (str, optional): The current working directory. Defaults to None.
        verbose (bool, optional): Whether to print the executed command. Defaults to False.
        hide_stderr (bool, optional): Whether to hide the standard error. Defaults to False.
        env (dict, optional): The environment variables to be set. Defaults to None.

    Returns:
        str: The standard output of the command.
    """

    if not isinstance(commands, list) or not commands:
        raise ValueError("`commands` must be a non-empty list of strings.")

    if not isinstance(args, list) or not args:
        raise ValueError("`args` must be a non-empty list of strings.")

    if len(commands) != len(args):
        raise ValueError("`commands` and `args` must have the same length.")

    command_str = " ".join([*commands, *args])

    if verbose:
        print(command_str)

    if env:
        if not isinstance(env, dict):
            raise ValueError("`env` must be a dictionary.")

    try:
        process = subprocess.Popen(
            command_str,
            shell=True,
            cwd=cwd,
            env=env,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE
        )

        stdout, stderr = process.communicate()

        if process.returncode != 0:
            raise subprocess.CalledProcessError(process.returncode, command_str)

        if hide_stderr:
            return stdout.decode("utf-8")
        else:
            return stdout, stderr
    except FileNotFoundError as e:
        raise FileNotFoundError("The command was not found: {}".format(e.filename))

