def verifyObject(iface, candidate, tentative=False):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the interface using ``iface.providedBy`` (unless *tentative* is `True`, in which case this step is skipped). This means that the candidate's class declares that it `implements <zope.interface.implementer>` the interface, or the candidate itself declares that it `provides <zope.interface.provider>` the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be checked passed.
    :raises zope.interface.Invalid: If any of the previous conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors are collected and reported. Previously, only the first error was reported. As a special case, if only one such error is present, it is raised alone, like before.
    """

    if not tentative:
        if not iface.providedBy(candidate):
            raise zope.interface.Invalid(f"Object does not provide interface '{iface.__name__}'")

    required_methods, required_attributes = iface.getNamesIn()

    # Make sure all required methods are defined
    for method in required_methods:
        if not hasattr(candidate, method):
            raise zope.interface.Invalid(f"The required method '{method}' is not defined")

    # Check signature of all methods
    for method in required_methods:
        signature = getargspec(getattr(candidate, method))
        if signature.args != iface.getMethodSignature(method):
            raise zope.interface.Invalid(f"The signature of '{method}' does not match the required signature")

    # Make sure all required attributes are defined
    for attribute in required_attributes:
        if not hasattr(candidate, attribute):
            raise zope.interface.Invalid(f"The required attribute '{attribute}' is not defined")

