        raise ValueError(f"Class {candidate.__name__} does not implement interface {iface.__name__}")

    # check if all required methods are implemented
    for method in iface.__abstractmethods__:
        if method not in candidate.__dict__:
            raise ValueError(f"Class {candidate.__name__} must implement method {method}")
        elif not callable(candidate.__dict__[method]):
            raise ValueError(f"Class {candidate.__name__} must provide a callable implementation of method {method}")

    # check if all optional methods have a default implementation or are implemented in the candidate
    for method in iface.__dict__:
