                raise ValueError(f"Class {candidate.__name__} must provide an implementation of optional method {method}")
        elif not callable(candidate.__dict__[method]):
            # if the candidate has a non-callable implementation of the method
            raise ValueError(f"Class {candidate.__name__} must provide a callable implementation of optional method {method}")

