def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if not bases:
        return
    metaclasses = [b.__class__ for b in bases if isinstance(b, type)]
    if explicit_mc is not None:
        metaclasses.append(explicit_mc)
    base_metas = set()
    for b in metaclasses:
        if b not in base_metas:
            base_metas.add(b)
    if len(base_metas) > 1:
        raise TypeError("Metaclass conflict: the metaclass of a derived class must be a (non-strict) superset of the metaclasses of all its bases")
    return next(iter(base_metas), None)

