def popitem(self):
    """Remove and return the (key, value) pair least recently used."""
    if len(self.data) == 0:
        raise KeyError("LRUCache is empty")

    # Find the oldest entry
    oldest_key = None
    oldest_value = None
    for key, value in self.data.items():
        if oldest_key is None or value < oldest_value:
            oldest_key = key
            oldest_value = value

    # Remove the oldest entry from the dictionary
    del self.data[oldest_key]

    # If the cache is full, remove the oldest entry from the queue
    if len(self.data) == self.capacity:
        self.queue.popleft()

    return (oldest_key, oldest_value)

