    # Define a set of opening tags to ignore in code blocks.
    ign_tags = {'<code', '<pre', '<script', '<style'}

    # Initialize an empty set to store found tags.
    tags = set()

    # Replace all HTML tags with their corresponding closing tags.
    new_text = re.sub(r'<(\w+)[^>]*>', r'</\1>', text)

