    """Given a list of settings directories and a specification option, return a list of file names in those directories that match the specification option.

    Args:
        settings_dirs (list[str]): A list of settings directories
        spec_option (str): A specification option

    Returns:
        list[str]: A list of file names in the settings directories that match the specification option
    """
    file_names = []
    for settings_dir in settings_dirs:
        for root, dirs, files in os.walk(settings_dir):
