def create_complex_argumet_type(self, subcommand, type_name, option_name, spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    if not isinstance(subcommand, str):
        raise TypeError("subcommand must be a string")
    if not isinstance(type_name, str):
        raise TypeError("type_name must be a string")
    if not isinstance(option_name, str):
        raise TypeError("option_name must be a string")
    if not isinstance(spec_option, dict):
        raise TypeError("spec_option must be a dictionary")

    try:
        option_value = spec_option["default"]
        if option_value in ["True", "True", True]:
            option_value = True
        elif option_value in ["False", "False", False]:
            option_value = False
        elif isinstance(option_value, str) and len(option_value) == 0:
            option_value = None

        if "enum" in spec_option.keys():
            option_type = str(spec_option["enum"][0])
        else:
            option_type = str(spec_option["type"])

        if option_type == "string":
            option_type = str
        elif option_type == "integer":
            option_type = int
        elif option_type == "number":
            option_type = float
        elif option_type == "boolean":
            option_type = bool
        else:
            raise ValueError("Unknown option type: {}".format(option_type))

        complex_type = type_name(option_name, option_type, option_value, spec_option)
    except KeyError:
        raise KeyError("spec_option is missing required key: {}".format(key))
    except Exception:
        raise Exception("Error creating complex argument type")

    return complex_type

