    """Wraps the 'ansible-playbook' CLI.

    :param ir_workspace: An Infrared Workspace object represents the active workspace
    :param ir_plugin: An InfraredPlugin object of the current plugin
    :param playbook_path: the playbook to invoke
    :param verbose: Ansible verbosity level
    :param extra_vars: dict. Passed to Ansible as extra-vars
    :param ansible_args: dict of ansible-playbook arguments to plumb down directly to Ansible.
    """
    if not ir_workspace.available:
        raise ValueError("The workspace is not available")
    if not ir_plugin.available:
        raise ValueError("The plugin is not available")
    if not os.path.exists(playbook_path):
        raise ValueError("The playbook does not exist")

    if ansible_args is None:
        ansible_args = {}

    if verbose is not None:
        if verbose not in [0, 1, 2, 3, 4]:
            raise ValueError("Invalid verbose level")
        ansible_args["verbosity"] = verbose

    if extra_vars is not None:
        ansible_args["extra-vars"] = "@"+str(extra_vars)

    # Set the default value for the first argument
    if ansible_args["inventory"] is None:
        ansible_args["inventory"] = ir_workspace.get_property("ansible-hosts")

    # Set the default value for the second argument
    if ansible_args["limit"] is None:
        ansible_args["limit"] = ir_workspace.get_property("ansible-limit")

    # Set the default value for the third argument
    if ansible_args["connection"] is None:
        ansible_args["connection"] = ir_workspace.get_property("ansible-connection")

    # Set the default value for the fourth argument
    if ansible_args["module-path"] is None:
        ansible_args["module-path"] = ir_plugin.working_dir

    # Run ansible-playbook
    args = ["ansible-playbook", playbook_path]
    for key, value in ansible_args.items():
        if value is not None:
            args.append(key)
            args.append(value)
    returncode, stdout, stderr = run_command(args, cwd=ir_plugin.working_dir)

    # Print the output
    print(stdout)

